use crate::wasi::clocks::wall_clock;

struct Node;

/// Convert days since 1970-01-01 to a (year, month, day) civil date.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

/// Always exactly 10 characters: YYYY-MM-DD, clamped to years 0000..=9999.
fn format_date(seconds: u64) -> String {
    // Cap days well past year 9999 so the arithmetic cannot overflow.
    let days = core::cmp::min(seconds / 86_400, 3_000_000) as i64;
    let (y, m, d) = civil_from_days(days);
    let (y, m, d) = if y > 9_999 {
        (9_999, 12, 31)
    } else if y < 0 {
        (0, 1, 1)
    } else {
        (y, m, d)
    };
    let s = format!("{:04}-{:02}-{:02}", y, m, d);
    if s.len() == 10 {
        s
    } else {
        String::from("1970-01-01")
    }
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        RunInfo {
            date: format_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
